// The shared adapter exposes every md* uniform, so every preset gets a working
// parameter box: universal controls (declared + consumed by the adapter) plus
// the MilkDrop motion/wave/object knobs. Defaults come from each preset config.
const MD_PARAMS: ParameterSchema[] = [
  { id: 'speed', label: 'Speed', min: 0, max: 3, default: 1, step: 0.1, group: 'animation' },
  { id: 'intensity', label: 'Intensity', min: 0, max: 2, default: 1, step: 0.05, group: 'audio' },
  { id: 'brightness', label: 'Brightness', min: 0, max: 2, default: 1, step: 0.05, group: 'color' },
  { id: 'hueShift', label: 'Hue Shift', min: 0, max: 6.28, default: 0, step: 0.05 },
  { id: 'saturation', label: 'Saturation', min: 0, max: 2, default: 1, step: 0.05 },
  { id: 'mdZoom', label: 'Zoom', min: 0.01, max: 16, default: 1, step: 0.05, group: 'transform' },
  { id: 'mdRot', label: 'Rotation', min: -6.5, max: 1.5, default: 0, step: 0.05, group: 'transform' },
  { id: 'mdDecay', label: 'Decay', min: 0.5, max: 1, default: 0.98, step: 0.005, group: 'animation' },
  { id: 'mdWarp', label: 'Warp', min: 0, max: 1.5, default: 0, step: 0.005, group: 'audio' },
  { id: 'mdGamma', label: 'Gamma', min: 1, max: 8, default: 2, step: 0.05, group: 'color' },
  { id: 'mdWaveMode', label: 'Wave Mode', min: 0, max: 7, default: 0, step: 1, group: 'shape' },
  { id: 'mdWaveAlpha', label: 'Wave Alpha', min: 0, max: 2, default: 0.5, step: 0.01, group: 'audio' },
  { id: 'mdWaveFreq', label: 'Wave Freq', min: -2, max: 2, default: 0, step: 0.05, group: 'shape' },
  { id: 'mdObSize', label: 'Ob Size', min: 0, max: 0.5, default: 0.1, step: 0.005, group: 'shape' },
  { id: 'mdObAlpha', label: 'Ob Alpha', min: 0, max: 1, default: 0, step: 0.01, group: 'audio' },
]

export const MILKDROP_PRESETS: ShaderDefinition[] = RAW_MILKDROP_PRESETS.map(p => ({
  ...p,
  params: MD_PARAMS.map(s => ({ ...s, default: p.defaults[s.id] ?? s.default })),
}))
